parameters.command:
=ls -p {{ $json.directorio_monitoreado }} | grep -v / || true; \
echo "==="; \
ls -p {{ $json.directorio_monitoreado }} | grep / || true;

=directorio="{{ $('Set variable directorio').item.json.directorio_monitoreado }}"
subdirectorio="$directorio/{{ $json.folder }}";
lista_archivos="{{ $json.files.join(' ') }}";

# crear subdirectorio si no existe
mkdir -p $subdirectorio;

# para cada sugerencia, mueva el archivo al subdirectorio.
# Si el archivo en el subdirectorio existe, entonces renombraremos el archivo actual añadiendo una pequeña cadena aleatoria al final del nombre del archivo.
for nombre_archivo in $lista_archivos; do
    if [ -e "$subdirectorio/$nombre_archivo" ]; then
        mv "$directorio/$nombre_archivo-$RANDOM" -t $subdirectorio;
    else
        mv "$directorio/$nombre_archivo" -t $subdirectorio;
    fi
done
